{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spf_mp_final AS SELECT t.*, CASE WHEN UPPER(status) IN (\'APPROVED\', \'ACCEPT\', \'PAYMENT_COMPLETED\') THEN \'Approved\' WHEN UPPER(status) IN (\'REJECTED\', \'REJECT\') THEN \'Rejected\' ELSE \'pending\' END AS final_status, CASE WHEN REJECTIONREASON ILIKE \'%same brand%\' OR REJECTIONREASON ILIKE \'%catalog%\' OR REJECTIONREASON ILIKE \'%not charged%\' OR REJECTIONREASON ILIKE \'%wrong size%\' OR REJECTIONREASON ILIKE \'%item_code%\' OR REJECTIONREASON ILIKE \'%claim_value%\' OR REJECTIONREASON ILIKE \'%cannot consider%\' OR REJECTIONREASON ILIKE \'%damage/used part%\' THEN \'Same brand equal price\' WHEN REJECTIONREASON ILIKE \'%out%tat%\' OR REJECTIONREASON ILIKE \'%tat breach%\' OR REJECTIONREASON ILIKE \'%beyond%tat%\' THEN \'Out tat\' WHEN REJECTIONREASON ILIKE \'%vms%\' THEN \'VMS\' WHEN REJECTIONREASON ILIKE \'%wfr%\' THEN \'WFR\' WHEN REJECTIONREASON ILIKE \'%video%\' OR REJECTIONREASON ILIKE \'%cctv%\' OR REJECTIONREASON ILIKE \'%360%\' OR REJECTIONREASON ILIKE \'%footage%\' OR REJECTIONREASON ILIKE \'%packing%\' OR REJECTIONREASON ILIKE \'%image%\' OR REJECTIONREASON ILIKE \'%six sided%\' OR REJECTIONREASON ILIKE \'%label%\' THEN \'video issue\' WHEN REJECTIONREASON ILIKE \'%tamper%\' OR REJECTIONREASON ILIKE \'%repack%\' OR REJECTIONREASON ILIKE \'%already opened%\' THEN \'tampered shipment\' WHEN REJECTIONREASON ILIKE \'%no response%\' THEN \'No response from seller\' WHEN REJECTIONREASON ILIKE \'%invalid%\' OR REJECTIONREASON ILIKE \'%not eligible%\' OR REJECTIONREASON ILIKE \'%duplicate%\' OR REJECTIONREASON ILIKE \'%insufficient%\' OR REJECTIONREASON ILIKE \'%wrong%\' OR REJECTIONREASON ILIKE \'%return delivered%\' OR REJECTIONREASON ILIKE \'%rto%\' THEN \'Invalid claim\' ELSE \'other\' END AS final_rejection_reason, CASE WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%FAKE%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%DIFFERENT BRAND%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%WRONG PRODUCT%\' THEN \'Fake\' WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%SHORT%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%MISSING%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%EMPTY BOX%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%PARTIAL%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%INCOMPLETE%\' THEN \'Short Qty\' WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%DAMAGE%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%STAIN%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%DEFECTIVE%\' THEN \'damage\' WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%WRONG RETURNS%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%WPR%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%SAME BRAND%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%STICK%\' THEN \'wpr\' ELSE \'other\' END AS final_issuecategory, TO_CHAR(parsed_date, \'Mon-YYYY\') AS month_display, TO_CHAR(parsed_date, \'YYYY-MM\') AS month_order, YEAR(parsed_date) AS year FROM ( SELECT *, COALESCE( TRY_TO_TIMESTAMP_TZ(CREATEDON), TRY_TO_TIMESTAMP(CREATEDON), TRY_TO_DATE(CREATEDON, \'YYYY-MM-DD\'), CASE WHEN REGEXP_LIKE(CREATEDON, \'^\d{4}-\d{2}-\d{2}$\') THEN TRY_TO_DATE( SUBSTR(CREATEDON,1,4) || \'-\' || SUBSTR(CREATEDON,9,2) || \'-\' || SUBSTR(CREATEDON,6,2), \'YYYY-MM-DD\' ) END, TRY_TO_DATE(CREATEDON, \'DD-MM-YYYY\'), TRY_TO_DATE(CREATEDON, \'DD/MM/YYYY\'), TRY_TO_DATE(CREATEDON, \'MM-DD-YYYY\'), TRY_TO_DATE(CREATEDON, \'MM/DD/YYYY\'), TRY_TO_DATE(CREATEDON, \'DD-MON-YYYY\'), TRY_TO_DATE(CREATEDON, \'DD-MON-YY\'), DATEADD( DAY, TRY_TO_NUMBER(CREATEDON), \'1899-12-30\' ) ) AS parsed_date FROM spf_mp ) t;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

